CREATE TABLE `UserMfa` (`userId` INTEGER NOT NULL, `secretCiphertext` TEXT NOT NULL, `enabledAt` DATETIME(3) NULL, `lastAcceptedStep` BIGINT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`userId`));
CREATE TABLE `MfaChallenge` (`id` VARCHAR(30) NOT NULL, `userId` INTEGER NOT NULL, `tokenHash` CHAR(64) NOT NULL, `expiresAt` DATETIME(3) NOT NULL, `attempts` INTEGER NOT NULL DEFAULT 0, `consumedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `MfaChallenge_tokenHash_key` (`tokenHash`), INDEX `MfaChallenge_userId_expiresAt_idx` (`userId`,`expiresAt`));
CREATE TABLE `MfaRecoveryCode` (`id` VARCHAR(30) NOT NULL, `userId` INTEGER NOT NULL, `codeHash` CHAR(64) NOT NULL, `usedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `MfaRecoveryCode_codeHash_key` (`codeHash`), INDEX `MfaRecoveryCode_userId_usedAt_idx` (`userId`,`usedAt`));
CREATE TABLE `Notification` (`id` VARCHAR(30) NOT NULL, `userId` INTEGER NOT NULL, `type` VARCHAR(100) NOT NULL, `payload` JSON NOT NULL, `readAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), INDEX `Notification_userId_readAt_createdAt_idx` (`userId`,`readAt`,`createdAt`));
ALTER TABLE `UserMfa` ADD CONSTRAINT `UserMfa_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `Usuario`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `MfaChallenge` ADD CONSTRAINT `MfaChallenge_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `Usuario`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `MfaRecoveryCode` ADD CONSTRAINT `MfaRecoveryCode_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `Usuario`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `Notification` ADD CONSTRAINT `Notification_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `Usuario`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
